from pathlib import Path
import json,html
r=Path(__file__).resolve().parent
slugs=['motion-comic-aulia','paper-cutout-aulia','bold-vector-aulia','doodle-aulia','retro-halftone-aulia']
configs=[dict(slug=s,**json.loads((r/s/'pack.json').read_text())) for s in slugs]
master=json.loads((r/'pixel-aulia/manifest.json').read_text())
options=''.join('<option value="'+a['file']+'">'+html.escape(a['id'].replace('-',' ').title())+'</option>' for a in master['assets'])
cards=''.join(f'<article><h2>{html.escape(c["style"])}</h2><div class="tile"><img src="{c["slug"]}/characters/netral.png" data-style="{c["slug"]}" alt="Aulia dalam gaya {html.escape(c["style"])}"></div><p>{html.escape(c["description"])}</p><a href="{c["slug"]}/preview.html">Buka paket · 46 aset</a></article>' for c in configs)
page='''<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aulia · Style Explorer</title><style>*{box-sizing:border-box}body{margin:0;padding:28px;background:#111827;color:#f9fafb;font-family:system-ui}header,main,footer{max-width:1360px;margin:0 auto 26px}p{color:#c0cbdc;line-height:1.6}main{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:20px}article{padding:18px;border:1px solid #4b5563;border-radius:12px;background:#1e293b}h2{margin:0 0 16px}.tile{height:390px;border-radius:8px;background:var(--bg,#0b1220);display:flex;align-items:center;justify-content:center}.tile img{max-width:100%;max-height:100%;object-fit:contain}a{color:#93c5fd}select,button{background:#25334b;color:white;border:1px solid #718096;border-radius:6px;padding:10px;margin:5px;cursor:pointer}body[data-bg="light"]{--bg:#f5eddb}body[data-bg="check"] .tile{background:repeating-conic-gradient(#b9bec8 0% 25%,#e5e7ec 0% 50%) 50%/24px 24px}button[aria-pressed="true"]{background:#365b8a}@media(max-width:1100px){main{grid-template-columns:repeat(auto-fit,minmax(280px,1fr))}}@media(max-width:480px){body{padding:16px}.tile{height:330px}}</style><header><h1>Aulia · Lima Arah Visual</h1><p>Bandingkan karakter dan komposisi yang sama dalam lima gaya nonpixel. Total 230 PNG transparan: setiap gaya memiliki 13 pose, 24 reaksi dan 9 efek mandiri—setara Pixel Aulia.</p><label>Bandingkan pose <select id="pose">__OPTIONS__</select></label><div><button data-bg="dark" aria-pressed="true">Gelap</button><button data-bg="light" aria-pressed="false">Terang</button><button data-bg="check" aria-pressed="false">Transparansi</button></div><p>PNG diam. Bagian tubuh dan properti belum berupa layer terpisah; komponen Remotion menggerakkan gambar utuh dan layer sayap mandiri.</p></header><main>'''+cards+'''</main><footer><a href="pixel-aulia/preview.html">Koleksi Pixel Aulia</a></footer><script>document.querySelector('#pose').addEventListener('change',e=>document.querySelectorAll('img[data-style]').forEach(i=>i.src=i.dataset.style+'/'+e.target.value));document.querySelectorAll('button[data-bg]').forEach(b=>b.onclick=()=>{document.body.dataset.bg=b.dataset.bg;document.querySelectorAll('button[data-bg]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))})</script></html>'''
page=page.replace('__OPTIONS__',options)
(r/'style-explorer.html').write_text(page)
print('Wrote style explorer.')
